REPORT_HTML_TEMPLATE = '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Отчёт ОП — F2B PRO</title>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js"></script>\n<style>\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif; background: #f8f7ff; color: #1e1b4b; min-height: 100vh; }\n.header { background: #fff; border-bottom: 1px solid #e8e5f5; padding: 16px 24px; display: flex; align-items: center; justify-content: space-between; }\n.header h1 { font-size: 18px; font-weight: 600; color: #1e1b4b; }\n.header .date { font-size: 13px; color: #6b7280; }\n.container { max-width: 1100px; margin: 0 auto; padding: 24px 16px; }\n.summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin-bottom: 24px; }\n.card { background: #fff; border-radius: 12px; border: 1px solid #e8e5f5; padding: 14px 16px; }\n.card .label { font-size: 11px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px; }\n.card .value { font-size: 22px; font-weight: 600; color: #1e1b4b; }\n.card .pct { font-size: 12px; margin-top: 4px; }\n.pct.good { color: #059669; }\n.pct.warn { color: #d97706; }\n.pct.bad { color: #dc2626; }\n.tabs { display: flex; gap: 8px; margin-bottom: 20px; flex-wrap: wrap; }\n.tab { padding: 8px 16px; border-radius: 20px; border: 1.5px solid #e8e5f5; background: #fff; cursor: pointer; font-size: 13px; font-weight: 500; color: #6b7280; transition: all 0.15s; }\n.tab.active { background: #7c3aed; border-color: #7c3aed; color: #fff; }\n.tab:hover:not(.active) { border-color: #a78bfa; color: #7c3aed; }\n.chart-wrap { background: #fff; border-radius: 12px; border: 1px solid #e8e5f5; padding: 20px; margin-bottom: 20px; }\n.chart-title { font-size: 14px; font-weight: 500; color: #1e1b4b; margin-bottom: 16px; }\n.mgr-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; margin-bottom: 20px; }\n.mgr-card { background: #fff; border-radius: 12px; border: 1px solid #e8e5f5; padding: 16px; cursor: pointer; transition: all 0.15s; }\n.mgr-card:hover { border-color: #a78bfa; box-shadow: 0 2px 8px rgba(124,58,237,0.08); }\n.mgr-card.selected { border-color: #7c3aed; border-width: 2px; }\n.mgr-card .name { font-size: 14px; font-weight: 600; margin-bottom: 10px; color: #1e1b4b; }\n.mgr-card .lost { font-size: 11px; color: #dc2626; margin-top: 6px; }\n.metric-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }\n.metric-row .m-label { font-size: 11px; color: #6b7280; }\n.metric-row .m-val { font-size: 12px; font-weight: 500; color: #1e1b4b; }\n.bar-mini { height: 4px; background: #e8e5f5; border-radius: 2px; margin-bottom: 2px; }\n.bar-mini-fill { height: 100%; border-radius: 2px; background: #7c3aed; }\n.detail-panel { background: #fff; border-radius: 12px; border: 1px solid #e8e5f5; padding: 20px; }\n.detail-panel h3 { font-size: 16px; font-weight: 600; margin-bottom: 16px; }\n.loading { text-align: center; padding: 60px 20px; color: #6b7280; font-size: 15px; }\n.spinner { width: 32px; height: 32px; border: 3px solid #e8e5f5; border-top-color: #7c3aed; border-radius: 50%; animation: spin 0.8s linear infinite; margin: 0 auto 16px; }\n@keyframes spin { to { transform: rotate(360deg); } }\n.metric-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 16px; }\n.m-detail-card { background: #f8f7ff; border-radius: 8px; padding: 12px; }\n.m-detail-card .dl { font-size: 11px; color: #6b7280; margin-bottom: 4px; }\n.m-detail-card .df { font-size: 18px; font-weight: 600; }\n.m-detail-card .dp { font-size: 11px; margin-top: 2px; }\n</style>\n</head>\n<body>\n\n<div class="header">\n  <h1>Отчёт ОП — F2B PRO</h1>\n  <span class="date" id="report-date">Загрузка...</span>\n</div>\n\n<div class="container">\n  <div id="loading" class="loading">\n    <div class="spinner"></div>\n    Загружаю данные из МойСклад...\n  </div>\n\n  <div id="content" style="display:none">\n    <!-- Сводные карточки -->\n    <div class="summary" id="summary-cards"></div>\n\n    <!-- Табы по менеджерам -->\n    <div class="tabs" id="mgr-tabs"></div>\n\n    <!-- График -->\n    <div class="chart-wrap">\n      <div class="chart-title" id="chart-title">Выполнение плана</div>\n      <div style="position:relative; height:320px;">\n        <canvas id="mainChart"></canvas>\n      </div>\n    </div>\n\n    <!-- Карточки менеджеров -->\n    <div class="mgr-grid" id="mgr-cards"></div>\n\n    <!-- Детальная панель -->\n    <div class="detail-panel" id="detail-panel" style="display:none">\n      <h3 id="detail-name"></h3>\n      <div class="metric-detail" id="detail-metrics"></div>\n    </div>\n  </div>\n</div>\n\n<script>\nconst DATA = __REPORT_DATA__;\n\nconst COLORS = [\'#7c3aed\',\'#a855f7\',\'#c084fc\',\'#e879f9\',\'#f0abfc\'];\nconst MGR_COLORS = { \'Инесса\': \'#7c3aed\', \'Карина\': \'#a855f7\', \'Елена\': \'#c084fc\', \'Алексей\': \'#e879f9\' };\n\nconst METRICS_CONFIG = [\n  { key: \'revenue\',     label: \'Выручка\',      divisor: 1e6, suffix: \'млн\' },\n  { key: \'shipments\',   label: \'Отгрузки\',      divisor: 1,   suffix: \'\' },\n  { key: \'clients\',     label: \'Клиенты\',       divisor: 1,   suffix: \'\' },\n  { key: \'new_clients\', label: \'Новых клиентов\',divisor: 1,   suffix: \'\' },\n  { key: \'attracted\',   label: \'Привл.товары\',  divisor: 1e6, suffix: \'млн\' },\n];\n\nlet chart = null;\nlet selectedMgr = \'all\';\n\nfunction pct(fact, plan) {\n  if (!plan) return 0;\n  return Math.round(fact / plan * 100);\n}\n\nfunction pctClass(p) {\n  if (p >= 80) return \'good\';\n  if (p >= 50) return \'warn\';\n  return \'bad\';\n}\n\nfunction fmt(val, divisor, suffix) {\n  const v = val / divisor;\n  return (divisor === 1e6 ? v.toFixed(1) : Math.round(v)) + (suffix ? \' \' + suffix : \'\');\n}\n\nfunction renderSummary() {\n  const totals = { plan: {}, fact: {} };\n  METRICS_CONFIG.forEach(m => {\n    totals.plan[m.key] = Object.values(DATA.plans).reduce((s, p) => s + (p[m.key] || 0), 0);\n    totals.fact[m.key] = Object.values(DATA.facts).reduce((s, f) => s + (f[m.key] || 0), 0);\n  });\n\n  const html = METRICS_CONFIG.map(m => {\n    const p = pct(totals.fact[m.key], totals.plan[m.key]);\n    return `<div class="card">\n      <div class="label">${m.label}</div>\n      <div class="value">${fmt(totals.fact[m.key], m.divisor, m.suffix)}</div>\n      <div class="pct ${pctClass(p)}">${p}% из ${fmt(totals.plan[m.key], m.divisor, m.suffix)}</div>\n    </div>`;\n  }).join(\'\');\n  document.getElementById(\'summary-cards\').innerHTML = html;\n}\n\nfunction renderTabs() {\n  const mgrs = Object.keys(DATA.facts);\n  const tabs = [{ id: \'all\', label: \'Все\' }, ...mgrs.map(m => ({ id: m, label: DATA.short_names[m] || m }))];\n  document.getElementById(\'mgr-tabs\').innerHTML = tabs.map(t =>\n    `<div class="tab ${t.id === selectedMgr ? \'active\' : \'\'}" onclick="selectMgr(\'${t.id}\')">${t.label}</div>`\n  ).join(\'\');\n}\n\nfunction renderChart() {\n  const mgrs = selectedMgr === \'all\' ? Object.keys(DATA.facts) : [selectedMgr];\n  const labels = mgrs.map(m => DATA.short_names[m] || m);\n\n  const datasets = METRICS_CONFIG.map((m, i) => ({\n    label: m.label,\n    data: mgrs.map(mgr => Math.round((DATA.facts[mgr]?.[m.key] || 0) / m.divisor * 10) / 10),\n    backgroundColor: COLORS[i] + \'99\',\n    borderColor: COLORS[i],\n    borderWidth: 1,\n  }));\n\n  if (chart) chart.destroy();\n  chart = new Chart(document.getElementById(\'mainChart\'), {\n    type: \'bar\',\n    data: { labels, datasets },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: { display: true, position: \'bottom\', labels: { font: { size: 11 }, boxWidth: 10 } },\n        tooltip: {\n          callbacks: {\n            label: ctx => {\n              const m = METRICS_CONFIG[ctx.datasetIndex];\n              const plan = (DATA.plans[mgrs[ctx.dataIndex]]?.[m.key] || 0) / m.divisor;\n              const fact = ctx.raw;\n              const p = plan ? Math.round(fact / plan * 100) : 0;\n              return ` ${m.label}: ${fact}${m.suffix} / план ${Math.round(plan * 10)/10}${m.suffix} (${p}%)`;\n            }\n          }\n        }\n      },\n      scales: {\n        x: { grid: { display: false } },\n        y: { grid: { color: \'#f0effe\' }, ticks: { font: { size: 11 } } }\n      }\n    }\n  });\n\n  document.getElementById(\'chart-title\').textContent =\n    selectedMgr === \'all\' ? \'Выполнение плана — все менеджеры\' : `Выполнение плана — ${selectedMgr}`;\n}\n\nfunction renderMgrCards() {\n  const mgrs = selectedMgr === \'all\' ? Object.keys(DATA.facts) : [selectedMgr];\n  document.getElementById(\'mgr-cards\').innerHTML = mgrs.map(m => {\n    const f = DATA.facts[m] || {};\n    const p = DATA.plans[m] || {};\n    const short = DATA.short_names[m] || m;\n    const lost = f.lost_clients || 0;\n\n    const rows = METRICS_CONFIG.map(mc => {\n      const fv = (f[mc.key] || 0) / mc.divisor;\n      const pv = (p[mc.key] || 0) / mc.divisor;\n      const pc = pv ? Math.min(fv / pv, 1) : 0;\n      return `<div class="metric-row">\n        <span class="m-label">${mc.label}</span>\n        <span class="m-val">${fmt(f[mc.key]||0, mc.divisor, mc.suffix)}</span>\n      </div>\n      <div class="bar-mini"><div class="bar-mini-fill" style="width:${Math.round(pc*100)}%; background:${MGR_COLORS[short]||\'#7c3aed\'}"></div></div>`;\n    }).join(\'\');\n\n    return `<div class="mgr-card ${m === selectedMgr ? \'selected\' : \'\'}" onclick="showDetail(\'${m}\')">\n      <div class="name">${short}</div>\n      ${rows}\n      ${lost > 0 ? `<div class="lost">▼ выбыли: -${lost}</div>` : \'\'}\n    </div>`;\n  }).join(\'\');\n}\n\nfunction showDetail(mgr) {\n  const f = DATA.facts[mgr] || {};\n  const p = DATA.plans[mgr] || {};\n  const short = DATA.short_names[mgr] || mgr;\n\n  document.getElementById(\'detail-name\').textContent = short;\n  document.getElementById(\'detail-metrics\').innerHTML = METRICS_CONFIG.map(m => {\n    const fv = fmt(f[m.key]||0, m.divisor, m.suffix);\n    const pv = fmt(p[m.key]||0, m.divisor, m.suffix);\n    const pc = pct(f[m.key]||0, p[m.key]||0);\n    return `<div class="m-detail-card">\n      <div class="dl">${m.label}</div>\n      <div class="df">${fv}</div>\n      <div class="dp ${pctClass(pc)}">${pc}% из ${pv}</div>\n    </div>`;\n  }).join(\'\');\n\n  document.getElementById(\'detail-panel\').style.display = \'block\';\n  document.getElementById(\'detail-panel\').scrollIntoView({ behavior: \'smooth\' });\n}\n\nfunction selectMgr(id) {\n  selectedMgr = id;\n  renderTabs();\n  renderChart();\n  renderMgrCards();\n  document.getElementById(\'detail-panel\').style.display = \'none\';\n}\n\nfunction init() {\n  document.getElementById(\'report-date\').textContent = DATA.date;\n  document.getElementById(\'loading\').style.display = \'none\';\n  document.getElementById(\'content\').style.display = \'block\';\n  renderSummary();\n  renderTabs();\n  renderChart();\n  renderMgrCards();\n}\n\ninit();\n</script>\n</body>\n</html>\n'
